// kudbEE Think Token Dashboard — Real-time learning visualization
//
// Data honesty: This dashboard displays only real data from:
// - WebSocket 'thought' events (dispatched by app.js from every message)
// - Persisted tokens (created only when ThinkTokenFactory quality gate passes)
// - No timer-generated mock events, no fabricated propagation stats
//
// Demo events (decompose, swarm, jury, commons) are only generated by the cube's
// runDeterministicDemo() method when explicitly invoked by the user.

class ThinkTokenDashboard {
  constructor() {
    this.tokens = [];
    this.currentJobId = null;
    this.currentRunStatus = null;
    // The cube is created once, here, detached from the document — it keeps receiving real
    // 'think-cube:thought' events (dispatched by app.js from every WebSocket thought) whether
    // or not the modal below is currently open. openDashboard() just re-parents this same live
    // node into the modal each time, so the lifecycle it shows was not started by opening the
    // dialog. Without window.ThinkCubeRenderer (the module script failed to load), there's
    // simply no cube — degrade gracefully with no fake visualization.
    this.cube = window.ThinkCubeRenderer ? new window.ThinkCubeRenderer(document.createElement('div')) : null;
    this.modalEl = null;
    this.setupEventListeners();
  }

  setupEventListeners() {
    // Wire header button on DOMContentLoaded
    const learnBtn = document.getElementById('think-token-button');
    if (learnBtn) {
      learnBtn.addEventListener('click', () => this.openDashboard());
    }

    // Listen for real token creation events
    window.addEventListener('token:created', (e) => this.addToken(e.detail));
    window.addEventListener('token:used', (e) => this.recordTokenUsage(e.detail));

    // Real bridge: app.js dispatches this for every WebSocket 'thought' message.
    // The cube handles these directly via its handleThought() method.
    window.addEventListener('think-cube:thought', (e) => {
      const thought = e.detail;
      this.cube?.handleThought(thought);
      // Track current run/job context
      if (thought.type === 'goal') this.currentJobId = thought.run_id || thought.job_id;
      if (thought.type === 'think_token' || thought.type === 'memory') this.currentRunStatus = 'completed';
      this.updateCurrentJobInfo();
    });
  }

  addToken(tokenData) {
    const token = {
      id: tokenData.id || `token-${Date.now()}`,
      type: tokenData.type || 'reasoning',
      content: tokenData.content || '',
      confidence: tokenData.confidence || 0.5,
      createdAt: Date.now(),
      usageCount: 0,
      successCount: 0,
      failureCount: 0
    };

    this.tokens.unshift(token);
    // Only update if the dashboard is open
    if (this.modalEl) {
      this.renderTokenList();
    }
  }

  recordTokenUsage(usageData) {
    const token = this.tokens.find(t => t.id === usageData.tokenId);
    if (token) {
      token.usageCount++;
      if (usageData.success) {
        token.successCount++;
      } else {
        token.failureCount++;
      }
      token.confidence = this.calculateConfidence(token);
      // Only update if the dashboard is open
      if (this.modalEl) {
        this.renderTokenList();
      }
    }
  }

  calculateConfidence(token) {
    if (token.usageCount === 0) return token.confidence || 0.5;
    const successRate = token.successCount / token.usageCount;
    return Math.min(1, Math.max(0, successRate * 0.9 + (token.confidence || 0.5) * 0.1));
  }

  updateCurrentJobInfo() {
    if (!this.modalEl) return;
    const infoEl = this.modalEl.querySelector('.current-job-info');
    if (!infoEl) return;

    infoEl.innerHTML = `
      <div class="job-info-item">
        <span class="job-info-label">Current Job</span>
        <span class="job-info-value">${this.currentJobId ? this.currentJobId.substring(0, 12) : 'None'}</span>
      </div>
      <div class="job-info-item">
        <span class="job-info-label">Status</span>
        <span class="job-info-value">${this.currentRunStatus || 'Idle'}</span>
      </div>
      <div class="job-info-item">
        <span class="job-info-label">Tokens Created</span>
        <span class="job-info-value">${this.tokens.length}</span>
      </div>
    `;
  }

  openDashboard() {
    // Reuse existing modal if it's already open to preserve UI state
    if (this.modalEl && document.body.contains(this.modalEl)) {
      this.updateCurrentJobInfo();
      return;
    }

    const modal = document.createElement('div');
    modal.className = 'modal-backdrop';
    modal.id = 'think-token-modal';
    this.modalEl = modal;

    modal.innerHTML = `
      <section class="modal modal-dashboard" role="dialog" aria-modal="true">
        <div class="modal-header">
          <div>
            <span class="modal-eyebrow">🎫 LEARNING SYSTEM</span>
            <h2>Think Token Dashboard</h2>
          </div>
          <button class="btn-icon" aria-label="Close" onclick="this.closest('.modal-backdrop').remove()">×</button>
        </div>

        <div class="dashboard-layout">
          <!-- Primary: Live Cube + Current Job Info -->
          <div class="dashboard-primary">
            <div class="cube-section">
              <h3>🧊 Think Token Cube</h3>
              ${this.cube ? `
                <div class="think-cube-wrap"><div class="think-cube-slot"></div></div>
                <div class="cube-controls">
                  <button class="btn-quiet" data-cube-action="pause" title="Pause the cube visualization">⏸ Pause</button>
                  <button class="btn-quiet" data-cube-action="resume" title="Resume after pausing">▶ Resume</button>
                  <button class="btn-quiet" data-cube-action="reset" title="Reset to idle">↻ Reset</button>
                  <button class="btn-quiet" data-cube-action="replay" title="Replay recorded events">↺ Replay</button>
                  <button class="btn-quiet" data-cube-action="demo" title="Run demo of unimplemented stages">📺 Demo</button>
                </div>
                <details class="cube-legend-detail">
                  <summary>Learn about the cube</summary>
                  <div class="cube-legend-content">
                    <strong>Live signals from this run:</strong> intent (goal), execution (tool calls), evidence (successful results), challenge (tool errors), harvest (memory saved), think_token (completed).
                    <br><strong>Demo only (no backend signal yet):</strong> decompose, swarm, jury, commons. Click the Demo button to explore these.
                  </div>
                </details>
              ` : '<p class="cube-legend">Cube visualization unavailable (its module script did not load).</p>'}
            </div>

            <div class="current-job-section">
              <h3>📍 Current Run</h3>
              <div class="current-job-info"></div>
            </div>
          </div>

          <!-- Secondary: Tabbed view for history and analytics -->
          <div class="dashboard-secondary">
            <div class="tabs">
              <button class="tab-button active" data-tab="tokens" title="Recent tokens">Tokens (${this.tokens.length})</button>
              <button class="tab-button" data-tab="analytics" title="Token analytics">Analytics</button>
            </div>

            <div class="tab-content">
              <div class="tab-pane active" id="tab-tokens">
                ${this.tokens.length === 0
                  ? '<p class="empty-state">No tokens created yet. Tokens are created when a run completes with learned observations.</p>'
                  : `
                    <div class="token-list">
                      ${this.tokens.slice(0, 10).map(token => this.renderTokenCard(token)).join('')}
                    </div>
                  `
                }
              </div>

              <div class="tab-pane" id="tab-analytics">
                <div class="analytics-grid">
                  ${this.tokens.length === 0
                    ? '<p class="empty-state">No analytics available. Create tokens to see insights.</p>'
                    : `
                      <div class="analytics-card">
                        <h4>Token Confidence</h4>
                        <div class="confidence-tiers">
                          <div class="tier high-confidence">
                            <span class="tier-label">High (>70%)</span>
                            <span class="tier-count">${this.tokens.filter(t => t.confidence > 0.7).length}</span>
                          </div>
                          <div class="tier medium-confidence">
                            <span class="tier-label">Medium (40-70%)</span>
                            <span class="tier-count">${this.tokens.filter(t => t.confidence >= 0.4 && t.confidence <= 0.7).length}</span>
                          </div>
                          <div class="tier low-confidence">
                            <span class="tier-label">Low (<40%)</span>
                            <span class="tier-count">${this.tokens.filter(t => t.confidence < 0.4).length}</span>
                          </div>
                        </div>
                      </div>
                      <div class="analytics-card">
                        <h4>Token Types</h4>
                        <div class="type-bars">
                          ${this.getTokenTypeDistribution().map(([type, count]) => `
                            <div class="type-bar">
                              <span class="type-name">${type}</span>
                              <div class="bar-container">
                                <div class="bar-fill" style="width: ${(count / Math.max(...this.getTokenTypeDistribution().map(x => x[1]))) * 100}%"></div>
                              </div>
                              <span class="type-count">${count}</span>
                            </div>
                          `).join('')}
                        </div>
                      </div>
                      <div class="analytics-card">
                        <h4>Success Rate</h4>
                        <div class="metric-display">
                          <span class="metric-value">${this.calculateAverageSuccessRate()}%</span>
                          <span class="metric-label">Average across all tokens</span>
                        </div>
                      </div>
                    `
                  }
                </div>
              </div>
            </div>
          </div>
        </div>

        <div class="modal-actions">
          <button class="btn-secondary" onclick="thinkTokenDashboard.exportLearnings()">Export Learning</button>
          <button class="btn-secondary" onclick="document.getElementById('think-token-modal')?.remove()">Close</button>
        </div>
      </section>
    `;

    modal.addEventListener('click', (e) => {
      if (e.target === modal) {
        modal.remove();
        this.modalEl = null;
      }
    });

    // Tab switching
    modal.querySelectorAll('.tab-button').forEach(btn => {
      btn.addEventListener('click', () => this.switchTab(btn.dataset.tab, modal));
    });

    document.body.appendChild(modal);

    // Set up cube in the slot
    if (this.cube) {
      const slot = modal.querySelector('.think-cube-slot');
      slot.appendChild(this.cube.container);
      slot.insertAdjacentElement('afterend', this.cube.statusEl);
      this.cube.statusEl.insertAdjacentElement('afterend', this.cube.inspectEl);
      this.cube.render();

      const actions = {
        pause: () => this.cube.pause(),
        resume: () => this.cube.resume(),
        reset: () => this.cube.reset(),
        replay: () => this.cube.replay(),
        demo: () => this.cube.runDeterministicDemo(),
      };
      modal.querySelectorAll('[data-cube-action]').forEach((btn) => {
        btn.addEventListener('click', () => actions[btn.dataset.cubeAction]?.());
      });
    }

    this.updateCurrentJobInfo();
  }

  switchTab(tabName, modal) {
    // Update active tab button
    modal.querySelectorAll('.tab-button').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.tab === tabName);
    });

    // Update active pane
    modal.querySelectorAll('.tab-pane').forEach(pane => {
      pane.classList.toggle('active', pane.id === `tab-${tabName}`);
    });
  }

  renderTokenCard(token) {
    const safeId = this.escapeHtml(token.id);
    const safeContent = this.escapeHtml(token.content.substring(0, 100));
    return `
      <div class="token-card" data-token-id="${safeId}">
        <div class="token-header">
          <span class="token-type ${token.type}">${this.getTypeIcon(token.type)} ${token.type}</span>
          <span class="token-confidence">${(token.confidence * 100).toFixed(0)}%</span>
        </div>
        <div class="token-content">${safeContent}${token.content.length > 100 ? '...' : ''}</div>
        <div class="token-meta">
          <span class="token-age">${this.formatAge(token.createdAt)}</span>
          <span class="token-usage">${token.usageCount} uses</span>
          <span class="token-success">${token.successCount}✓ ${token.failureCount}✗</span>
        </div>
        <button class="token-expand btn-quiet" onclick="thinkTokenDashboard.showTokenDetails('${safeId}')">Details</button>
      </div>
    `;
  }

  renderTokenList() {
    if (!this.modalEl) return;
    const pane = this.modalEl.querySelector('#tab-tokens');
    if (!pane) return;

    if (this.tokens.length === 0) {
      pane.innerHTML = '<p class="empty-state">No tokens created yet.</p>';
    } else {
      pane.innerHTML = `<div class="token-list">${this.tokens.slice(0, 10).map(token => this.renderTokenCard(token)).join('')}</div>`;
    }
  }

  showTokenDetails(tokenId) {
    const token = this.tokens.find(t => t.id === tokenId);
    if (!token) return;

    const detailModal = document.createElement('div');
    detailModal.className = 'modal-backdrop';
    detailModal.innerHTML = `
      <section class="modal modal-token-details" role="dialog" aria-modal="true">
        <div class="modal-header">
          <h2>${this.getTypeIcon(token.type)} ${token.type.toUpperCase()}</h2>
          <button class="btn-icon" onclick="this.closest('.modal-backdrop').remove()">×</button>
        </div>

        <div class="token-details-content">
          <div class="detail-section">
            <h4>Content</h4>
            <pre><code>${this.escapeHtml(token.content)}</code></pre>
          </div>

          <div class="detail-section">
            <h4>Metrics</h4>
            <ul>
              <li>Created: ${new Date(token.createdAt).toLocaleString()}</li>
              <li>Confidence: ${(token.confidence * 100).toFixed(1)}%</li>
              <li>Total Uses: ${token.usageCount}</li>
              <li>Successes: ${token.successCount}</li>
              <li>Failures: ${token.failureCount}</li>
              <li>Success Rate: ${token.usageCount > 0 ? ((token.successCount / token.usageCount) * 100).toFixed(1) : 'N/A'}%</li>
            </ul>
          </div>

          <div class="detail-section">
            <h4>Status</h4>
            <span class="status-badge ${token.confidence > 0.7 ? 'active' : 'learning'}">
              ${token.confidence > 0.7 ? '✓ Ready for Propagation' : '🔄 Still Learning'}
            </span>
          </div>
        </div>

        <div class="modal-actions">
          <button class="btn-secondary" onclick="this.closest('.modal-backdrop').remove()">Close</button>
        </div>
      </section>
    `;

    detailModal.addEventListener('click', (e) => {
      if (e.target === detailModal) detailModal.remove();
    });

    document.body.appendChild(detailModal);
  }

  getTokenTypeDistribution() {
    const dist = {};
    this.tokens.forEach(t => {
      dist[t.type] = (dist[t.type] || 0) + 1;
    });
    return Object.entries(dist).sort((a, b) => b[1] - a[1]);
  }

  getTypeIcon(type) {
    const icons = {
      reasoning: '🤔',
      approach: '📋',
      error_recovery: '🔧',
      tool_sequence: '⚙️',
      optimization: '⚡'
    };
    return icons[type] || '🎫';
  }

  calculateAverageSuccessRate() {
    if (this.tokens.length === 0) return 0;
    const rates = this.tokens
      .filter(t => t.usageCount > 0)
      .map(t => (t.successCount / t.usageCount) * 100);
    return rates.length > 0 ? Math.round(rates.reduce((a, b) => a + b) / rates.length) : 0;
  }

  calculateKnowledgeReuse() {
    const totalPotential = this.tokens.length * 100;
    const actualReuse = this.tokens.reduce((sum, t) => sum + t.usageCount, 0);
    return totalPotential > 0 ? Math.round((actualReuse / totalPotential) * 100) : 0;
  }

  formatAge(timestamp) {
    const age = Date.now() - timestamp;
    const minutes = Math.floor(age / 60000);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);

    if (days > 0) return `${days}d ago`;
    if (hours > 0) return `${hours}h ago`;
    if (minutes > 0) return `${minutes}m ago`;
    return 'just now';
  }

  escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text || '';
    return div.innerHTML;
  }


  exportLearnings() {
    const data = {
      exportedAt: new Date().toISOString(),
      tokenCount: this.tokens.length,
      tokens: this.tokens,
      analysis: {
        avgSuccessRate: this.calculateAverageSuccessRate(),
        knowledgeReuse: this.calculateKnowledgeReuse()
      }
    };

    const json = JSON.stringify(data, null, 2);
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `think-tokens-${Date.now()}.json`;
    a.click();
  }

}

document.addEventListener('DOMContentLoaded', () => {
  window.thinkTokenDashboard = new ThinkTokenDashboard();
});
